<script lang="ts">
 import {onDestroy} from "svelte";import {reportEditorDirty} from "./editor-drafts";
 export let editorId="";
 import {monthlyPersons} from "./occupancy";
 import {uid,today,type Project,type Account} from './model';import {saveAccountDocument,type AccountDocument} from './account-lifecycle';import {translator} from './i18n';import {displayDate} from './date-format';import RecordToolbar from './RecordToolbar.svelte';import {Save,Check,X} from '@lucide/svelte';
 export let project:Project;export let kind:AccountDocument['kind'];export let initial:AccountDocument|null=null;export let onapply:(p:Project)=>void;export let onedit:(d:AccountDocument)=>void;export let onclose:()=>void;
 let draft=initial?structuredClone(initial):null,selected='',error='';$:t=translator(project.settings.language);$:locked=draft?.state==='applied';$:documents=project.account_documents.filter(d=>d.kind===kind);$:current=documents.find(d=>d.id===selected);
 function blank():Account{return {id:uid(),number:'',payer_name:'',address:'',apartments:[],total_area_m2:'0',registered_residents:0,waste_charge_persons:0,opening_balance:'0.00',opening_period:project.settings.period,service_ids:project.services.filter(s=>s.active).map(s=>s.id),active:true,notes:'',custom_fields:{}};}
 function create(){const first=project.accounts.find(a=>kind!=='close'||a.active);const selected=first?structuredClone(first):blank();if(first&&kind==='information')selected.waste_charge_persons=monthlyPersons(project,first,project.settings.period).persons??first.waste_charge_persons;onedit({id:uid(),number:String(project.account_documents.length+1),date:kind==='services'?project.settings.period+'-01':today(),kind,state:'draft',account:kind==='open'||!first?blank():selected,comment:''});}
 function save(post=false,close=false){if(!draft)return;try{const next=saveAccountDocument(project,draft,post);onapply(next);draft=structuredClone(next.account_documents.find(d=>d.id===draft!.id)!);error='';savedDraft=JSON.stringify(draft);reportEditorDirty(editorId,false);if(close)onclose();}catch(e){error=e instanceof Error?e.message:String(e);}}
 function selectAccount(id:string){const account=project.accounts.find(a=>a.id===id);if(account&&draft)draft={...draft,account:{...structuredClone(account),waste_charge_persons:kind==='information'?(monthlyPersons(project,account,draft.date.slice(0,7)).persons??account.waste_charge_persons):account.waste_charge_persons}};}
 let savedDraft=JSON.stringify(draft);
 $:reportEditorDirty(editorId,!!draft&&(!project.account_documents.some(d=>d.id===draft!.id)||JSON.stringify(draft)!==savedDraft));
 onDestroy(()=>reportEditorDirty(editorId,false));
</script>
<div class="account-documents">{#if error}<p class="alert error" role="alert">{error}</p>{/if}
{#if !draft}<RecordToolbar language={project.settings.language} selected={!!current} onadd={create} onedit={()=>current&&onedit(structuredClone(current))} oncopy={()=>{if(current)onedit({...structuredClone(current),id:uid(),number:String(project.account_documents.length+1),date:today(),state:'draft',before:undefined});}} onrefresh={()=>selected=''} onpost={()=>{if(current)try{onapply(saveAccountDocument(project,current,true));error='';}catch(e){error=String(e);}}} canPost={current?.state==='draft'}/><table><thead><tr><th>{t('Дата','Data')}</th><th>{t('Номер','Număr')}</th><th>{t('Лицевой счёт','Cont personal')}</th><th>{t('Комментарий','Comentariu')}</th><th>{t('Статус','Stare')}</th></tr></thead><tbody>{#each documents as doc}<tr class:selected={selected===doc.id} class:attention-row={doc.state==='draft'} onclick={()=>selected=doc.id} ondblclick={()=>onedit(structuredClone(doc))}><td>{displayDate(doc.date,project)}</td><td>{doc.number}</td><td>{doc.account.number} · {doc.account.payer_name}</td><td>{doc.comment}</td><td>{doc.state==='applied'?t('Проведён','Aplicat'):t('Черновик','Ciornă')}</td></tr>{/each}</tbody></table>
{:else}<fieldset disabled={locked}><div class="document-header"><label>{t('Дата','Data')}<input type="date" bind:value={draft.date}/></label><label>{t('Номер','Număr')}<input bind:value={draft.number}/></label></div>
{#if kind!=='open'}<label>{t('Лицевой счёт','Cont personal')}<select value={draft.account.id} onchange={e=>selectAccount(e.currentTarget.value)}>{#each project.accounts as a}<option value={a.id}>{a.number} · {a.payer_name}</option>{/each}</select></label>{/if}
{#if kind==='open'||kind==='information'}<nav>{t('Основное','Principal')}</nav><div class="fields"><label>{t('Номер лицевого счёта','Numărul contului')}<input bind:value={draft.account.number} disabled={kind!=='open'}/></label><label>{t('Ответственный потребитель','Consumator responsabil')}<input bind:value={draft.account.payer_name}/></label><label>{t('Адрес','Adresă')}<input bind:value={draft.account.address}/></label><label>{t('Общая площадь, м²','Suprafață totală, m²')}<input bind:value={draft.account.total_area_m2}/></label><label>{t('Зарегистрировано','Înregistrați')}<input type="number" min="0" bind:value={draft.account.registered_residents}/></label><label>{t('Проживающих для платы за мусор','Locatari pentru plata deșeurilor')}<input type="number" min="0" bind:value={draft.account.waste_charge_persons}/></label></div>{/if}
{#if kind==='open'||kind==='services'}<section><h3>{t('Услуги лицевого счёта','Serviciile contului')}</h3>{#each project.services as service}<label class="check-row"><input type="checkbox" checked={draft.account.service_ids.includes(service.id)} onchange={e=>{if(draft)draft.account.service_ids=e.currentTarget.checked?[...draft.account.service_ids,service.id]:draft.account.service_ids.filter(id=>id!==service.id);}}/>{service.name[project.settings.language]}</label>{/each}</section>{/if}
{#if kind==='opening-balance'||kind==='open'}<label>{t('Начальный остаток, MDL','Sold inițial, MDL')}<input bind:value={draft.account.opening_balance}/></label>{/if}
{#if kind==='close'}<p>{t('Закрытие сохраняет историю счёта, начисления и оплаты. Счёт остаётся доступен для просмотра.','Închiderea păstrează istoricul contului, calculele și plățile. Contul rămâne disponibil pentru vizualizare.')}</p>{/if}
<label>{t('Комментарий','Comentariu')}<input bind:value={draft.comment}/></label></fieldset>
<footer>{#if !locked}<button class="button" onclick={()=>save(true,true)}><Check size={16}/>{t('Провести и закрыть','Aplică și închide')}</button><button class="button secondary" onclick={()=>save()}><Save size={16}/>{t('Сохранить','Salvează')}</button>{/if}<button class="button secondary" onclick={onclose}><X size={16}/>{t('Закрыть','Închide')}</button></footer>{/if}</div>
<style>.account-documents{display:flex;flex-direction:column;gap:12px;padding:12px}fieldset{border:0;padding:0;display:flex;flex-direction:column;gap:14px;min-width:0}.document-header,.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:flex;flex-direction:column;gap:6px}.check-row{flex-direction:row;align-items:center;margin:6px 0}nav{padding:8px 0;border-bottom:2px solid var(--accent)}input,select{min-width:0}table{border-collapse:collapse;width:100%}th,td{padding:8px;text-align:left}th{background:#80808020}.selected{background:#489bcb30}footer{display:flex;gap:8px;justify-content:flex-end;padding-top:12px}</style>
